drawOverlayBox(ctx) {
  ctx.fillStyle = "rgba(255,255,255,0.88)";  // 88% opaque white
  ctx.strokeStyle = "#ccc";

  ctx.lineWidth = 2;
  ctx.beginPath();

  ctx.roundRect(100, 60, 300, 200);;  // centered: 200px margin each side
  ctx.fill();
  ctx.stroke();
}

draw() {
  ctx.clearRect(...);

  // draw bricks, paddle, ball
  if (this.state === STATE.MENU)      this.drawMenuOverlay(ctx);

  if (this.state === STATE.PAUSED)    this.drawPausedOverlay(ctx);

  if (this.state === STATE.GAME_OVER) this.drawGameOverOverlay(ctx);
}
